-- =============================================================================
-- GrounUp Enterprise — 0010 Row Level Security
--
-- Every table in `public` is force-enabled for RLS. Policies are generated by
-- two audited helpers rather than hand-written sixty times, because a
-- hand-written policy set is exactly where a single omitted table becomes a
-- cross-tenant data leak.
--
-- 0011 asserts that no table in `public` was left without RLS, so adding a table
-- without a policy fails the build rather than shipping open.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Policy generators
-- -----------------------------------------------------------------------------

/**
 * Standard policy set for a table whose company_id is NOT NULL.
 *
 * SELECT   : the row's company is one the user is an active member of.
 * INSERT   : same, plus the write permission, and the new row's company must be
 *            one the user belongs to — a member of two companies cannot insert
 *            into the one they are not writing as.
 * UPDATE   : USING and WITH CHECK both applied, so a row cannot be moved
 *            between tenants by updating company_id.
 * DELETE   : membership plus the delete permission.
 */
create or replace function app.apply_tenant_rls(
  p_table text,
  p_read_permission text default null,
  p_write_permission text default null,
  p_delete_permission text default null
)
returns void
language plpgsql
as $$
declare
  v_read  text := case when p_read_permission is null
                       then format('app.is_member(%I.company_id)', p_table)
                       else format('(app.is_member(%I.company_id) and app.has_permission(%I.company_id, %L))',
                                   p_table, p_table, p_read_permission) end;
  v_write text := case when p_write_permission is null
                       then format('app.is_member(company_id)')
                       else format('(app.is_member(company_id) and app.has_permission(company_id, %L))', p_write_permission) end;
  v_del   text := case when coalesce(p_delete_permission, p_write_permission) is null
                       then format('app.is_member(%I.company_id)', p_table)
                       else format('(app.is_member(%I.company_id) and app.has_permission(%I.company_id, %L))',
                                   p_table, p_table, coalesce(p_delete_permission, p_write_permission)) end;
begin
  execute format('alter table %I enable row level security', p_table);
  execute format('alter table %I force row level security', p_table);

  execute format('drop policy if exists %I on %I', p_table || '_select', p_table);
  execute format('create policy %I on %I for select to authenticated using (%s)',
                 p_table || '_select', p_table, v_read);

  execute format('drop policy if exists %I on %I', p_table || '_insert', p_table);
  execute format('create policy %I on %I for insert to authenticated with check (%s)',
                 p_table || '_insert', p_table, v_write);

  execute format('drop policy if exists %I on %I', p_table || '_update', p_table);
  execute format('create policy %I on %I for update to authenticated using (%s) with check (%s)',
                 p_table || '_update', p_table,
                 replace(v_write, 'app.is_member(company_id)', format('app.is_member(%I.company_id)', p_table)),
                 v_write);

  execute format('drop policy if exists %I on %I', p_table || '_delete', p_table);
  execute format('create policy %I on %I for delete to authenticated using (%s)',
                 p_table || '_delete', p_table, v_del);
end;
$$;

/**
 * Policy set for a three-tier library table (global / enterprise group / company).
 *
 * SELECT lets a member read the GrounUp global seed, their group's corporate
 * standard, and their own company's overrides. Writes are confined to their own
 * company: no tenant can edit the global seed or another group's standard, which
 * is what keeps a shared library trustworthy.
 */
create or replace function app.apply_library_rls(
  p_table text,
  p_write_permission text default 'libraries.write'
)
returns void
language plpgsql
as $$
declare
  v_read text := format($f$(
      (%1$I.company_id is null and %1$I.enterprise_group_id is null)
      or app.is_member(%1$I.company_id)
      or %1$I.enterprise_group_id in (
        select c.enterprise_group_id from companies c
        where c.id in (select app.current_company_ids()) and c.enterprise_group_id is not null
      )
    )$f$, p_table);
  v_write text := format(
    '(company_id is not null and app.is_member(company_id) and app.has_permission(company_id, %L))',
    p_write_permission);
  v_write_using text := format(
    '(%1$I.company_id is not null and app.is_member(%1$I.company_id) and app.has_permission(%1$I.company_id, %2$L))',
    p_table, p_write_permission);
begin
  execute format('alter table %I enable row level security', p_table);
  execute format('alter table %I force row level security', p_table);

  execute format('drop policy if exists %I on %I', p_table || '_select', p_table);
  execute format('create policy %I on %I for select to authenticated using (%s)',
                 p_table || '_select', p_table, v_read);

  execute format('drop policy if exists %I on %I', p_table || '_insert', p_table);
  execute format('create policy %I on %I for insert to authenticated with check (%s)',
                 p_table || '_insert', p_table, v_write);

  execute format('drop policy if exists %I on %I', p_table || '_update', p_table);
  execute format('create policy %I on %I for update to authenticated using (%s) with check (%s)',
                 p_table || '_update', p_table, v_write_using, v_write);

  execute format('drop policy if exists %I on %I', p_table || '_delete', p_table);
  execute format('create policy %I on %I for delete to authenticated using (%s)',
                 p_table || '_delete', p_table, v_write_using);
end;
$$;

